new = '''    <section className="rounded-[28px] border border-border/70 bg-background/90 p-4 shadow-sm sm:p-6">\n      <div className="mb-4 flex items-end justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#9a6d12]">LDR Plataforma</p><h2 className="mt-1 font-serif text-2xl sm:text-3xl">{sectionTitle}</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">{sectionSubtitle}</p></div></div>\n      <div className="flex gap-3 overflow-x-auto pb-2 snap-x snap-mandatory">\n        <div className="min-w-[145px] max-w-[170px] flex-1 snap-start rounded-2xl bg-[#5b0824] p-4 text-white shadow-sm">\n          <BookOpen className="h-6 w-6"/><p className="mt-3 text-sm font-black">eBooks</p>\n          {ebookProduct?.entitled?<a href="/cliente/biblioteca/ebook_coragem_comecar" className="mt-3 block rounded-xl bg-white/12 p-3 text-xs leading-4 transition hover:bg-white/20"><span className="block font-bold">A Coragem de Começar</span><span className="mt-1 block text-white/75">{ebookProgress?`${ebookProgress.progress_percent}% · `:""}{copy.accessState}</span></a>:<a href="#library-ebook_coragem_comecar" className="mt-3 block text-xs font-bold text-white/80 underline">{copy.buyState}</a>}\n        </div>\n        <div className="min-w-[145px] max-w-[170px] flex-1 snap-start rounded-2xl bg-[#0b2341] p-4 text-white shadow-sm">\n          <BookOpen className="h-6 w-6"/><p className="mt-3 text-sm font-black">Livros</p>\n          {bookProduct?.entitled?<a href="/cliente/biblioteca/livro_menino_mamao" className="mt-3 block rounded-xl bg-white/12 p-3 text-xs leading-4 transition hover:bg-white/20"><span className="block font-bold">O Menino que Vendia Mamão</span><span className="mt-1 block text-white/75">{bookProgress?`${bookProgress.progress_percent}% · `:""}{copy.accessState}</span></a>:<a href="#library-livro_menino_mamao" className="mt-3 block text-xs font-bold text-white/80 underline">{copy.buyState}</a>}\n        </div>\n        <div className="min-w-[145px] max-w-[170px] flex-1 snap-start rounded-2xl bg-[#d6ad63] p-4 text-[#281605] shadow-sm">\n          <GraduationCap className="h-6 w-6"/><p className="mt-3 text-sm font-black">Treinamentos</p>\n          {trainingOffer?.entitled?<a href="/cliente/treinamentos/do-mamao-ao-negocio" className="mt-3 block rounded-xl bg-white/35 p-3 text-xs leading-4 transition hover:bg-white/50"><span className="block font-bold">Do Mamão ao Negócio</span><span className="mt-1 block opacity-75">{trainingOffer.progressPercent}% · {copy.accessState}</span></a>:<a href="#library-training" className="mt-3 block text-xs font-bold underline">{copy.buyState}</a>}\n        </div>\n        <div className="min-w-[145px] max-w-[170px] flex-1 snap-start rounded-2xl bg-[#35101e] p-4 text-white shadow-sm">\n          <Film className="h-6 w-6"/><p className="mt-3 text-sm font-black">{copy.film}</p>\n          <div className="mt-3 rounded-xl border border-white/15 bg-white/8 p-3 text-xs leading-4"><span className="block font-bold">{copy.filmTitle}</span><span className="mt-1 block text-white/70">{copy.filmState}</span></div>\n        </div>\n      </div>\n    </section>'''
