s = s.replace('    <section className="grid min-w-0 gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-label={copy.title}>\n      {data.products.map((product)=>{', '    {hasIndividualOffers?<section className="grid min-w-0 gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-label={copy.title}>\n      {data.products.filter((product)=>!product.entitled).map((product)=>{', 1)
s = s.replace('      <article id="library-training" className="scroll-mt-24 flex min-h-[350px]', '      {!trainingOffer?.entitled?<article id="library-training" className="scroll-mt-24 flex min-h-[350px]', 1)
s = s.replace('</div></div></article>\n\n      <article id="library-film"', '</div></div></article>:null}\n\n      <article id="library-film"', 1)
